struct Cache {                         // COW storage: swapping moves one reference
    private var state: State

    mutating func swapState(with other: inout Cache) {
        swap(&state, &other.state)     // stdlib swap: cannot throw
    }
}

var xs = [1, 2, 3, 4]
xs.swapAt(0, 3)                        // collections: swapAt, never swap(&xs[0], &xs[3])
